mapper.select:
select t1.id, t1.comment_id, t1.reply_content, t1.location, t1.audit_status, t1.create_time, t1.create_user_id, ifnull(t2.nick_name, t2.username) as create_user_name from book_comment_reply t1 left join user t2 on t1.create_user_id = t2.id where t1.comment_id = #{commentId}
and t1.reply_content like concat('%', #{keyword}, '%')
order by t1.create_time desc
